<template><div><h1>Edit item</h1><AppInput v-model="name"/><AppButton @click="save">Update</AppButton></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {itemsApi} from '../api/client';import AppInput from '../components/AppInput.vue';import AppButton from '../components/AppButton.vue';const route=useRoute();const router=useRouter();const name=ref('');onMounted(async()=>{name.value=(await itemsApi.get(route.params.id as string)).data.name;});const save=async()=>{const item=(await itemsApi.get(route.params.id as string)).data;await itemsApi.update(route.params.id as string,{...item,name:name.value,expiryDate:item.expiryDate?.slice(0,10)});router.push('/inventory');};</script>
